fn unnecessary_spread_fix(
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    let source = locator.contents();
    let mut coordinator = DictLiteralCoordinator::default();
    let doublestar = coordinator.find_double_star(prev_end, source)?;

    // Delete the `**`, any parentheses around the dictionary, and the opening `{`,
    // while preserving comments and whitespace in between.
    let mut edits = vec![];
    for token in SimpleTokenizer::new(
        source,
        TextRange::new(doublestar.start(), dict.start() + TextSize::from(1)),
    )
    .skip_trivia()
    {
        edits.push(Edit::range_deletion(token.range()));
        if token.kind() == SimpleTokenKind::LBrace {
            break;
        }
    }

    // Delete any trailing comma, the closing `}`, and any parentheses around the
    // dictionary, while preserving comments and whitespace in between.
    let start = dict
        .iter_values()
        .last()
        .map_or(dict.start() + TextSize::from(1), Ranged::end);
    let mut closed = false;
    for token in SimpleTokenizer::starts_at(start, source).skip_trivia() {
        match token.kind() {
            SimpleTokenKind::Comma if !closed => {
                edits.push(Edit::range_deletion(token.range()));
            }
            SimpleTokenKind::RBrace if !closed => {
                edits.push(Edit::range_deletion(token.range()));
                closed = true;
            }
            SimpleTokenKind::RParen if closed => {
                edits.push(Edit::range_deletion(token.range()));
            }
            _ => break,
        }
    }

    let mut edits = edits.into_iter();
    let first = edits.next()?;
    Some(Fix::safe_edits(first, edits))
}

